 "content": "from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            component = set(cells)
            perimeter = ([(r0,c) for c in range(c0,c1+1)] + [(r1,c) for c in range(c0,c1+1)] +
                         [(r,c0) for r in range(r0,r1+1)] + [(r,c1) for r in range(r0,r1+1)])
            if all(p in component for p in perimeter):
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        if out[y][x] == 0:
                            out[y][x] = 8
    return out
